/* Admin workspace. A displayed provider is not a verified connection. */
let dataCenterTab='storage',dataCenterStatus=null,dataCenterError='',dataCenterBusy=false,accessSearch='';
function dataCenterShortcut(){return '<div class="data-center-shortcut">'+uiIcon('settings-2')+'<div><b>'+tx('البيانات والصلاحيات','Data & access')+'</b><p>'+tx('مكان التخزين، ربط Google، حسابات المستخدمين والنسخ الاحتياطي.','Storage, Google setup, user access and backups.')+'</p></div><button class="btn primary" data-nav="data">'+tx('فتح مركز الإدارة','Open admin centre')+'</button></div>';}
function dataCenterPage(){
 if(role!=='admin')return '<div class="notice">'+tx('هذه الصفحة لمسؤول النظام.','Administrator access required.')+'</div>';
 const mode=LIVE?tx('نسخة Google Workspace','Google Workspace edition'):tx('عرض تجريبي • على هذا الجهاز','Demo • on this device');
 const tabs=[['storage',tx('التخزين والربط','Storage & connection'),'folder-closed'],['accounts',tx('الحسابات والصلاحيات','Accounts & access'),'users-round'],['backups',tx('النسخ الاحتياطي','Backups'),'download']];
 return heading('',tx('تحكّم في بيانات شركتك، واعرف أين تُحفظ ومن يستطيع الوصول إليها.','Control company data, where it lives and who can access it.'))+
 '<section class="data-mode '+(LIVE?'live':'demo')+'"><span class="data-mode-icon">'+uiIcon(LIVE?'globe':'folder-closed')+'</span><div><span class="eyebrow">'+tx('بيئة العمل الحالية','CURRENT ENVIRONMENT')+'</span><h2>'+mode+'</h2><p>'+(LIVE?tx('السجلات على حساب الشركة في Google، والصلاحيات تُراجع على الخادم.','Company records are held in Google. The server checks permissions.'):tx('التغييرات محفوظة في هذا المتصفح فقط. لا توجد قاعدة بيانات سحابية أو كلمات مرور حقيقية متصلة بهذا العرض.','Changes stay in this browser. No cloud database or real password accounts are connected to this demo.'))+'</p></div><span class="badge '+(LIVE?'blue':'amber')+'">'+(LIVE?tx('هوية Google','Google identity'):tx('Google غير متصل','Google not connected'))+'</span></section>'+
 '<nav class="data-tabs" aria-label="'+tx('أقسام إدارة البيانات','Data administration sections')+'">'+tabs.map(t=>'<button class="'+(dataCenterTab===t[0]?'active':'')+'" data-action="dataTab" data-id="'+t[0]+'" aria-pressed="'+(dataCenterTab===t[0])+'">'+uiIcon(t[2])+t[1]+'</button>').join('')+'</nav><div class="data-panel">'+({storage:storagePanel,accounts:accountsPanel,backups:backupsPanel})[dataCenterTab]()+'</div>';
}
function storagePanel(){
 const tiles=[
  ['blue','users-round',tx('بيانات الموارد البشرية','HR records'),LIVE?'Google Sheets':tx('هذا المتصفح','This browser'),tx('الموظفون، الرواتب، الإجازات ومسارات الموافقة.','Employees, payroll, leave and approval workflows.')],
  ['teal','folder-closed',tx('المستندات والمرفقات','Documents & attachments'),LIVE?'Google Drive':tx('تخزين محلي للمرفقات','Local document storage'),tx('مسوغات التعيين داخل أرشيف خاص بكل موظف.','Hiring documents in each employee’s private archive.')],
  ['violet','user-round',tx('الدخول وكلمات المرور','Sign-in & passwords'),LIVE?'Google Workspace':tx('محاكاة دخول فقط','Simulated sign-in only'),LIVE?tx('Google يتحقق من كلمة المرور؛ البرنامج يحتفظ بالبريد والدور فقط.','Google verifies the password; the app keeps only the email and role.'):tx('الدور وكلمة المرور التجريبية لا يوفران حماية لبيانات حقيقية.','Demo roles and the demo password do not protect real employee data.')]
 ];
 const records=[['employees',state.employees.length,tx('ملفات الموظفين','Employee records')],['requests',state.requests.length+state.leaves.length,tx('الطلبات والإجازات','Requests & leave')],['documents',state.documents.length,tx('مستندات التعيين','Hiring documents')],['payroll',state.payroll.length,tx('دورات الرواتب','Payroll runs')]];
 return '<div class="storage-map">'+tiles.map(t=>'<article class="storage-tile '+t[0]+'"><span class="storage-icon">'+uiIcon(t[1])+'</span><h3>'+t[2]+'</h3><strong>'+t[3]+'</strong><p>'+t[4]+'</p></article>').join('')+'</div>'+
 '<div class="data-columns">'+card(tx('Google Workspace','Google Workspace'),tx('حساب الشركة هو مالك البيانات','Your company account owns the data'),connectionSummary(),'<span class="badge '+(dataCenterStatus?'green':'amber')+'">'+(dataCenterStatus?tx('تم الفحص','Checked'):LIVE?tx('بانتظار الفحص','Not checked yet'):tx('غير متصل','Not connected'))+'</span>')+
 card(tx('إدارة السجلات','Manage records'),tx('كل العمليات من واجهة البرنامج','Manage everything through the application'),'<div class="data-records">'+records.map(r=>'<button data-nav="'+r[0]+'"><span>'+uiIcon(routeIcon(r[0]))+r[2]+'</span><b>'+fmt(r[1])+'</b>'+uiIcon(tx('chevron-left','chevron-right'))+'</button>').join('')+'</div><p class="data-note">'+tx('لا تحتاج فتح Excel أو تعديل الجداول. الأرقام تخص مساحة العمل الحالية.','No Excel or spreadsheet editing needed. Counts describe the current workspace.')+'</p>')+'</div>';
}
function connectionSummary(){
 let body='<p class="data-copy">'+(LIVE?tx('افحص وصول الخادم إلى السجلات ومجلد الأرشيف.','Check the server’s access to records and the archive folder.'):tx('نسخة Google تحتاج إعدادًا أوليًا على حساب الشركة. لصق رابط مجلد Drive وحده لا يربط البرنامج.','The Google edition needs one-time setup on the company account. A Drive folder link alone does not connect this app.'))+'</p>';
 if(dataCenterStatus){const d=dataCenterStatus;body+='<dl class="data-facts">'+[[tx('نطاق الشركة','Company domain'),d.domain],[tx('قاعدة البيانات','Database'),d.databaseName],[tx('مجلد الأرشيف','Archive folder'),d.archiveName],[tx('آخر فحص','Last checked'),dataTime(d.checkedAt)]].map(r=>'<div><dt>'+r[0]+'</dt><dd>'+esc(r[1])+'</dd></div>').join('')+'</dl>';}
 if(dataCenterError)body+='<p class="notice" role="alert">'+esc(dataCenterError)+'</p>';
 return body+'<div class="form-actions">'+(LIVE?'<button class="btn primary" data-action="dataCheck" '+(dataCenterBusy?'disabled':'')+'>'+uiIcon('check')+tx(dataCenterBusy?'جارٍ الفحص…':'فحص الاتصال',dataCenterBusy?'Checking…':'Check connection')+'</button>':btn(tx('إعداد ربط Google','Set up Google'),'cloudSetup','','primary'))+btn(tx('الدخول وكلمات المرور','About sign-in'),'authInfo')+'</div>';
}
function dataTime(value){if(!value)return tx('لم يُسجّل بعد','Not recorded yet');const date=new Date(value);return Number.isNaN(date.getTime())?String(value):new Intl.DateTimeFormat(uiLang==='en'?'en-GB':'ar-EG',{dateStyle:'medium',...(/^\d{4}-\d{2}-\d{2}$/.test(value)?{}:{timeStyle:'short'})}).format(date);}
function accessDirectoryRows(){
 const users=new Map();state.employees.forEach(e=>{if(e.email)users.set(e.email.toLowerCase(),{email:e.email.toLowerCase(),name:e.name,role:'employee',status:e.status});});
 (state.access||[]).forEach(a=>{const email=a.email.toLowerCase();users.set(email,{...users.get(email),email,role:a.role});});
 const q=accessSearch.trim().toLocaleLowerCase();return [...users.values()].filter(a=>!q||[a.email,a.name||'',dataRoleName(a.role)].join(' ').toLocaleLowerCase().includes(q)).sort((a,b)=>a.email.localeCompare(b.email));
}
function dataRoleName(value){return value==='employee'?tx('موظف','Employee'):roleName(value);}
function accountsPanel(){
 const rows=accessDirectoryRows();
 return '<div class="notice blue">'+(LIVE?tx('الدخول بحساب Google Workspace للشركة. تغيير الدور هنا لا ينشئ بريدًا أو يغيّر كلمة المرور.','Sign in with a company Google Workspace account. Changing a role here does not create an email account or change its password.'):tx('الحسابات المعروضة تجريبية. تغيير الصلاحيات هنا يحاكي السلوك ولا ينشئ حساب دخول حقيقيًا.','These are demo accounts. Role changes simulate behaviour and do not create real sign-in accounts.'))+'</div>'+
 card(tx('حسابات مساحة العمل','Workspace accounts'),tx('الموظف يرى ملفه؛ الأدوار الإدارية تمنح وصولًا أوسع','Employees see their own record; administrative roles grant wider access'),
 '<div class="data-account-tools"><label for="accessSearch">'+tx('ابحث بالاسم أو البريد أو الدور','Search by name, email or role')+'</label><input id="accessSearch" type="search" value="'+esc(accessSearch)+'" autocomplete="off"><small>'+fmt(rows.length)+' '+tx('حساب','accounts')+'</small></div>'+
 table([tx('الاسم والبريد','Name & email'),tx('الدور','Role'),tx('حالة الوصول','Access status'),tx('الإجراء','Action')],rows.map(a=>'<tr><td><b>'+esc(a.name||tx('حساب إداري','Administrative account'))+'</b><small class="account-email" dir="ltr">'+esc(a.email)+'</small></td><td><span class="badge blue">'+esc(dataRoleName(a.role))+'</span></td><td><span class="badge '+(a.status==='inactive'?'red':'green')+'">'+(a.status==='inactive'?tx('موقوف داخل البرنامج','Blocked in this app'):tx('مسموح حسب الدور','Allowed by role'))+'</span></td><td>'+btn(tx('تعديل الدور','Edit role'),'editAccess',a.email,'small')+'</td></tr>')),
 btn(tx('إضافة صلاحية','Assign access'),'accessForm','','primary'))+
 '<div class="data-account-footer"><p>'+tx('إيقاف حساب الموظف داخل البرنامج يتم عند إتمام إنهاء الخدمة. حساب Google نفسه تُديره الشركة بشكل منفصل.','An employee is blocked in this app when offboarding is completed. The company manages the Google account separately.')+'</p>'+btn(tx('أين تُدار كلمات المرور؟','Where are passwords managed?'),'authInfo')+'</div>';
}
function backupsPanel(){
 return '<div class="data-columns">'+card(tx('النسخة الاحتياطية','Data backup'),LIVE?tx('نسخة خاصة في Drive التابع للشركة','A private copy in company Drive'):tx('حفظ نسخة من بيانات العرض','Save a copy of demo records'),
 '<div class="backup-symbol">'+uiIcon('download')+'</div><h3>'+tx('آخر نسخة على Google Drive','Last backup on Google Drive')+'</h3><p class="backup-time">'+(LIVE?esc(dataTime(dataCenterStatus?.lastBackupAt||dataCenterStatus?.lastBackupDate)):tx('لا توجد نسخة سحابية متصلة','No connected cloud backup'))+'</p><p class="data-copy">'+(LIVE?tx('نسخة تلقائية عند أول تعديل كل يوم، ونسخة فورية عند طلبك. لا تُحذف النسخ تلقائيًا.','A backup is saved on the first change each day, plus manual backups on request. Backups are not automatically deleted.'):tx('تصدير نسخة يحفظ السجلات على جهازك. حذف بيانات المتصفح قد يفقدك تعديلات العرض والمرفقات المحلية.','Export saves the records on your device. Clearing browser data may remove demo changes and local attachments.'))+'</p><div class="form-actions">'+(LIVE?'<button class="btn primary" data-action="cloudBackup" '+(dataCenterBusy?'disabled':'')+'>'+tx(dataCenterBusy?'جارٍ الحفظ…':'إنشاء نسخة الآن',dataCenterBusy?'Saving…':'Create backup now')+'</button>'+btn(tx('تحديث الحالة','Refresh status'),'dataCheck'):btn(tx('تصدير نسخة محلية','Export local backup'),'exportData','','primary')+btn(tx('استيراد نسخة للعرض','Import demo backup'),'importData'))+'</div>'+(dataCenterError?'<p class="notice" role="alert">'+esc(dataCenterError)+'</p>':''))+
 card(tx('ماذا تحتوي النسخة؟','What is included?'),tx('السجلات منفصلة عن الملفات الأصلية','Records and original files are separate'),'<ul class="backup-includes"><li>'+uiIcon('check')+tx('بيانات الموظفين والطلبات والرواتب والإعدادات.','Employee records, requests, payroll and settings.')+'</li><li>'+uiIcon('check')+tx('الأدوار وسجل الإجراءات وبيانات وصف المستندات.','Roles, activity history and document metadata.')+'</li><li>'+uiIcon('folder-closed')+tx('الملفات الأصلية لا تدخل في نسخة السجلات؛ احتفظ بأرشيف المستندات أيضًا.','Original files are not included in the records backup; retain the document archive too.')+'</li></ul><p class="data-note">'+tx('استعادة قاعدة سحابية تحتاج إجراء استعادة واختبار من المسؤول التقني. زر الاستيراد هنا متاح لبيانات العرض المحلية فقط.','Cloud database recovery requires an administrator-led restore and validation. Import is only available for local demo data.')+'</p>')+'</div>';
}
function authInfo(){modal('<span class="eyebrow">'+tx('هوية المستخدم','USER IDENTITY')+'</span><h2>'+tx('كلمة المرور تُدار عند مزوّد الدخول','Passwords belong with the sign-in provider')+'</h2><div class="auth-options"><article><h3>Google Workspace</h3><p>'+tx('في النسخة المجهزة للربط، الموظف والأدمن يدخلون بحساب الشركة. Google يتحقق من كلمة المرور. البرنامج يحتفظ بالبريد والدور ويربط الموظف بملفه.','In the deployable edition, staff and admins sign in with company accounts. Google verifies passwords. The app stores an email and role linked to the employee profile.')+'</p><p>'+tx('إنشاء حساب Google أو إعادة تعيين كلمة مروره يتم من إدارة Google Workspace، بواسطة مسؤول الشركة.','A company Workspace administrator creates Google accounts and resets their passwords in Google Admin.')+'</p></article><article><h3>'+tx('دخول مستقل بيوزر وباسوورد','Independent username & password')+'</h3><p>'+tx('هذا الخيار غير متصل حاليًا. يحتاج مزوّد تسجيل دخول وقاعدة بيانات على الخادم، مع استرجاع الحساب والصلاحيات. Drive يحتفظ بالمستندات، وليس كلمات المرور.','This option is not connected. It needs a server-side identity provider and database, account recovery and permissions. Drive holds documents, not passwords.')+'</p></article></div><div class="form-actions">'+(LIVE?'<a class="btn" href="https://admin.google.com/" target="_blank" rel="noopener noreferrer">'+tx('فتح إدارة Google','Open Google Admin')+'</a>':'')+btn(tx('فهمت','Got it'),'close','','primary')+'</div>');}
function cloudSetup(){modal('<span class="eyebrow">GOOGLE WORKSPACE</span><h2>'+tx('ربط بيانات الشركة بالسحابة','Connect company data to the cloud')+'</h2><p>'+tx('إعداد لمرة واحدة بحساب الشركة، ثم إدارة العمل اليومي بالكامل من واجهة البرنامج.','One-time setup with the company account, then manage daily work entirely through the app.')+'</p><ol class="cloud-steps">'+[
 [tx('تجهيز حسابات الشركة','Prepare company accounts'),tx('تحتاج نطاق Google Workspace وإيميلات للموظفين والأدمن داخل نفس النطاق.','Use a Google Workspace domain with employee and admin accounts in the same domain.')],
 [tx('تثبيت نسخة Google','Install the Google edition'),tx('المسؤول التقني يحمّل الحزمة، يضيف ملفاتها الأربعة إلى Apps Script، ويضبط نطاق الشركة وبريد الأدمن.','A technical administrator downloads the package, adds its four files to Apps Script and sets the company domain and administrator email.')],
 [tx('إنشاء مكان التخزين','Create company storage'),tx('تشغيل setup مرة واحدة ينشئ قاعدة سجلات فارغة ومجلد Drive خاصًا تحت حساب مالك المشروع.','Running setup once creates an empty records database and a private Drive folder owned by the project owner.')],
 [tx('نشر وفحص الدخول','Deploy and verify sign-in'),tx('انشر داخل نطاق الشركة فقط. افتح رابط نسخة Google بالأدمن، أضف موظفًا، وافحص الدخول بحسابه قبل إدخال بيانات فعلية.','Deploy for the company domain only. Open the Google edition as an admin, add a test employee and verify their sign-in before entering real records.')]
 ].map((s,i)=>'<li><span>'+String(i+1).padStart(2,'0')+'</span><div><h3>'+s[0]+'</h3><p>'+s[1]+'</p></div></li>').join('')+'</ol><div class="notice blue">'+tx('تنزيل الحزمة لا يفعّل الاتصال في رابط العرض هذا. نسخة Google تعمل من رابطها بعد تثبيتها؛ بيانات العرض لا تُرفع تلقائيًا.','Downloading does not connect this demo URL. The installed Google edition runs at its own URL; demo records are not uploaded automatically.')+'</div><div class="form-actions"><a class="btn primary" href="Zarqa-People-Google-Workspace.zip" download>'+tx('تحميل نسخة Google Workspace','Download Google Workspace edition')+'</a>'+btn(tx('تفاصيل الدخول','Sign-in details'),'authInfo')+'</div>');}
async function checkDataConnection(makeBackup=false){
 if(role!=='admin'||dataCenterBusy)return;
 if(!LIVE){cloudSetup();return;}
 dataCenterBusy=true;dataCenterStatus=null;dataCenterError='';render();
 try{dataCenterStatus=await callServer(makeBackup?'admin.backup':'admin.status');if(makeBackup){state=await callServer('getState');toast(tx('تم حفظ نسخة خاصة في Drive','Private backup saved in Drive'));}}
 catch(error){dataCenterError=tx('تعذر إكمال العملية: ','Could not complete the operation: ')+String(error.message||error);}
 finally{dataCenterBusy=false;if(page==='data'&&role==='admin')render();}
}
document.addEventListener('click',event=>{
 const el=event.target.closest('[data-action]');if(!el)return;
 const action=el.dataset.action;
 if(['dataTab','dataCheck','cloudBackup','editAccess'].includes(action)&&role!=='admin')return;
 if(action==='dataTab'){if(['storage','accounts','backups'].includes(el.dataset.id)){dataCenterTab=el.dataset.id;render();}}
 if(action==='dataCheck')checkDataConnection();
 if(action==='cloudBackup')checkDataConnection(true);
 if(action==='editAccess')accessForm(el.dataset.id);
 if(action==='cloudSetup')cloudSetup();
 if(action==='authInfo')authInfo();
});
document.addEventListener('input',event=>{if(event.target.id!=='accessSearch'||role!=='admin')return;accessSearch=event.target.value;render();$('accessSearch').focus();});
